-- ===== 본문 재추출 반영 5/5 (parse800.py 생성) =====
-- 러닝헤더가 끼어든 본문/뒤바뀐 본문을 PDF에서 다시 추출한 값으로 교체. id·코스·진도는 그대로.
-- 이 파일 58행 / 전체 338행

UPDATE public.words SET meaning = '1999년 3월 ASEAN+3 정상회의에서 협력과제의 하나로 통화·금융협력을 제시하고 역내 금융지원체제를 구축하기로 합의함에 따라 2000년 5월 태국 치앙마이에서 개최된 ASEAN+3 재무장관', detailed_meaning = '1999년 3월 ASEAN+3 정상회의에서 협력과제의 하나로 통화·금융협력을 제시하고 역내 금융지원체제를 구축하기로 합의함에 따라 2000년 5월 태국 치앙마이에서 개최된 ASEAN+3 재무장관 회의에서 마련한 방안을 말한다. 이 방안에서는 아세안 스왑협정의 확대, 역내 환매조건부채권매매 활성화, 한·중·일과 아세안의 양자간 통화스왑계약 체결 및 네트워크화, 역내 감시체제 강화를 제시하였다. 이후 스왑규모의 불충분, 개별스왑계약의 한계 등 CMI(Chiang Mai Initiative)의 미비점을 보완하고 위기대응능력을 더욱 강화하기 위한 CMI 다자화 협정(CMIM; Chiang Mai Initiative Multilateralization)이 2010년 3월 발효됨으로써 CMI는 CMIM으로 전환되었다. 이에 따라 CMI에 의거하여 추진되었던 양자간 스왑체계가 다자간 스왑체계로 바뀌는 동시에 참가국이 확대되고 위기해결 목적의 공동기금이 조성되는 등 역내 금융지원체제의 실효성이 높아지게 되었다. 또한 역내 감시체제 강화를 위하여 기존의 경제동향 검토 및 정책협의(ERPD)와 별도로 역내 거시경제 및 금융상황을 감시·평가·보고하는 아세안+3 거시경제조사기구(AMRO)가 2011년 4월에 설립되었다.', related_words = ARRAY['동남아시아국가연합+한ㆍ중ㆍ일(ASEAN+3)','글로벌 금융안전망']::text[] WHERE id = 589;  -- 치앙마이 이니셔티브(CMI)
UPDATE public.words SET meaning = '상대적으로 금리가 낮은 국가의 통화로 자금을 빌려(carry) 금리가 높은 국가의 주식 채권 등의 자산에 투자(trade)하는 행위를 의미한다.', detailed_meaning = '상대적으로 금리가 낮은 국가의 통화로 자금을 빌려(carry) 금리가 높은 국가의 주식 채권 등의 자산에 투자(trade)하는 행위를 의미한다. 국제금융시장에서 주요한 캐리트레이드(Carry Trade)의 사례는 1990년대 후반 저금리의 일본 엔화를 차입하여 고금리의 신흥국 자산에 투자하였던 엔 캐리트레이드를 들 수 있다. 글로벌 금융위기를 겪으면서 미국이 기준금리를 0%대로 낮추었던 2008년 이후에는 낮은 금리의 미 달러화를 차입하여 미국 이외의 고금리 국가에 투자하는 달러 캐리트레이드가 확산되기도 하였다. 캐리트레이 드의 수익은 국가 간의 금리 차 및 환율변동 등에 따라 결정되므로 금리 차뿐만 아니라 차입 국가와 투자 국가의 환율 변동도 고려해야 하는 점에 그 특징이 있다. 즉 캐리트레이드는 주로 저금리로 자금을 조달하여 고금리에 투자하므로 높은 수익을 얻을 수 있으나, 자금을 차입한 후에 차입 국가의 통화가치가 상승하거나 투자 국가의 통화가치가 하락하는 경우는 오히려 환차손이 발생할 위험이 있다.', related_words = '{}'::text[] WHERE id = 593;  -- 캐리트레이드
UPDATE public.words SET meaning = '코리보(KORIBOR)는 국내 은행들이 서로 자금거래를 할 때 기준이 되는 금리를 말한다.', detailed_meaning = '코리보(KORIBOR)는 국내 은행들이 서로 자금거래를 할 때 기준이 되는 금리를 말한다. 금융시장이 발달하고 금융상품이 다양해지면서 국내에서도 영국 런던의 은행간 단기자금거래 시 적용되는 금리인 LIBOR(London Inter-Bank Offered Rate)와 같은 은행간 단기 자금거래의 기준금리를 도입할 필요성이 높아졌다. 이에 한국은행은 은행, 전국은행연합회 등과 협의를 거쳐 2004년 2월 단기 기준금리 도입방안을 구체화하고 수개월간의 시범운영을 거쳐 같은 해 7월 26일 정식으로 도입하게 되었다. 코리보의 총 6개의 기간물(1 주, 1·2·3·6·12개월)이 발표되고 있으며, 2025년 7월 현재 11개 은행이 제시한 만기별금리 중에서 상·하 각각 3개의 금리를 제외한 나머지 제시금리를 산술평균하여 산출된다. 코리보는 원칙적으로 매 영업일 오전 11시에 공표되고 당일 오후 3시 30분에 전국은행연합회 홈페이지에 게재된다. 한편 코리보의 벤치마크였던 LIBOR의 경우 2023년 6월이후 산출이 완전 중단되면서 SOFR(담보부 초단기 금리) 등 무위험지표금리(RFR)가 그자리를 대체하고 있다. 코리보 역시 금리호가의 기초가 되는 은행간 무담보 기일물거래가 미미하여 신뢰성이 낮아 일부 변동금리대출과 내부이전금리에서 제한적으로 활용되고 있다.', related_words = ARRAY['LIBOR','자금조달비용지수(COFIX)']::text[] WHERE id = 597;  -- 코리보
UPDATE public.words SET meaning = '콜머니(Call Money)는 콜론과 반대되는 개념으로 자금이 부족한 금융기관이 하루 또는 이틀 정도의 초단기 자금을 다른 금융기관으로부터 빌리는 것을 말한다.', detailed_meaning = '콜머니(Call Money)는 콜론과 반대되는 개념으로 자금이 부족한 금융기관이 하루 또는 이틀 정도의 초단기 자금을 다른 금융기관으로부터 빌리는 것을 말한다. 콜머니는 주로 일일 자금의 부족분을 해소하기 위한 수단으로 사용된다. 예를 들어, 은행이 고객의 예금 인출 요청이 많아 일시적으로 자금이 부족할 경우, 콜머니를 통해 다른 은행으로부터 자금을 빌려와 유동성을 확보할 수 있다. 이처럼 콜머니는 금융기관 간의 단기 자금 융통 메커니즘으로 작동하며, 금융 시스템의 안정성을 유지하는 데 중요한 역할을 한다. 콜거래에서 발생하는 이자율인 콜금리는 한국은행의 기준금리와 밀접한 연관이 있으며, 시중금리 전반에 영향을 미친다. 한국은행 기준금리의 상향조정 등으로 콜금리가 오르면 대출금리도 오르고, 예금금리도 상승하는 경향이 있다. 반대로 콜금리가 낮아지면 대출이 쉬워지고 시중에 자금이 풍부해져 경기 활성화에 도움이 될 수 있다. 콜머니는 단순한 하루짜리 자금 거래처럼 보이지만 실제로는 금융시장의 체온계 역할을 한다. 콜금리의 급등 은 금융기관 간 신뢰 저하나 유동성 위기를 의미할 수 있고 반대로 안정적인 콜금리는 시장이 원활히 작동하고 있다는 신호로 해석된다.', related_words = ARRAY['콜금리']::text[] WHERE id = 598;  -- 콜머니
UPDATE public.words SET meaning = '콜(Call)시장은 금융기관들이 일시적인 자금 과부족을 조절하기 위하여 상호간에 초단기로 자금을 차입하거나 대여하는 시장이다.', detailed_meaning = '콜(Call)시장은 금융기관들이 일시적인 자금 과부족을 조절하기 위하여 상호간에 초단기로 자금을 차입하거나 대여하는 시장이다. 금융기관은 고객을 상대로 예금을 받고 대출을 하는 과정에서 수시로 자금이 남기도 하고 모자라기도 하는데, 이러한 자금 과부족을 콜시장에서 금융기관 간 자금거래를 통하여 조절한다. 콜거래 만기는 최장 90일 이내에 서 일별로 정할 수 있으나, 금융기관의 일시적 자금 과부족을 조절하는 콜시장의 속성상실제 거래에서는 익일물(1일물)이 대부분을 차지하고 있다. 콜거래의 최소 거래금액은 1 억원이며, 거래단위는 억원이다. 거래이율의 변동 단위는 0.01%이다. 콜거래는 계약체결방식에 따라 중개거래와 직거래로 구분되는데 대부분의 거래는 중개거래로 이루어진다. 중개거래는 자금중개회사가 거래조건(이율, 만기, 금액 등)에 따라 자금의 공급자와 수요자를 연결시켜 주는 거래이다. 지급준비제도 적용 대상 금융기관(은행)들이 지급준비금 과부족을 주로 콜거래를 통해 조정하고 있다는 점에서 콜시장은 지준시장으로서의 의 미도 갖는다. 콜시장은 통화정책 수행에 있어서도 매우 중요한 위치를 차지하고 있다. 한 국은행 금융통화위원회가 결정하는 기준금리는 초단기금리인 콜금리를 통해 장단기 시장금리, 예금 및 대출금리, 궁극적으로는 실물경제 활동에 파급되기 때문이다. 이에 따라한국은행은 무담보 익일물 콜금리가 한국은행 기준금리 수준에서 크게 벗어나지 않도록공개시장운영 등을 통해 유동성을 조절하고 있다.', related_words = ARRAY['기준금리']::text[] WHERE id = 599;  -- 콜시장
UPDATE public.words SET meaning = 'CBAM은 EU 역외에서 생산돼 유럽연합(EU)로 수입되는 시멘트, 전기, 비료, 철·철강, 알루미늄, 수소 등 6가지 품목 제품을 생산하는 과정에서 나오는 탄소배출 추정치를 계산해 일종의 세금을', detailed_meaning = 'CBAM은 EU 역외에서 생산돼 유럽연합(EU)로 수입되는 시멘트, 전기, 비료, 철·철강, 알루미늄, 수소 등 6가지 품목 제품을 생산하는 과정에서 나오는 탄소배출 추정치를 계산해 일종의 세금을 부과하는 제도이다. 관세수준은 정해진 탄소배출량 초과량에 대한 배출권을 사고 파는 제도인 유럽연합 탄소배출권거래제를 가이드라인 삼아 책정된다. EU는 2026년부터 전면 시행할 예정이다.', related_words = '{}'::text[] WHERE id = 602;  -- 탄소국경세(Carbon Border Adjustment Mechanism, CBAM)
UPDATE public.words SET meaning = '탈세계화는 세계화의 반대되는 개념으로, 세계 각국간의 상호교류와 협력이 줄어들고 자국 중심적인 정책을 강화하는 현상을 말한다.', detailed_meaning = '탈세계화는 세계화의 반대되는 개념으로, 세계 각국간의 상호교류와 협력이 줄어들고 자국 중심적인 정책을 강화하는 현상을 말한다. 이는 정치, 경제, 사회, 문화 등 다양한 분야 에서 나타날 수 있으며, 보호무역주의 심화, 공급망 재편, 지역주의 강화 등으로 나타난다.', related_words = '{}'::text[] WHERE id = 605;  -- 탈세계화(De-globalization)
UPDATE public.words SET meaning = '테일러 준칙(Taylor’s Rule)이란 1993년 미국 경제학자인 존 테일러(John Taylor) 가 제안한 금리준칙으로 중앙은행이 거시경제 안정을 달성하기 위해 물가변동뿐만 아니라', detailed_meaning = '테일러 준칙(Taylor’s Rule)이란 1993년 미국 경제학자인 존 테일러(John Taylor) 가 제안한 금리준칙으로 중앙은행이 거시경제 안정을 달성하기 위해 물가변동뿐만 아니라 산출변동에도 금리가 조정되도록 한 금리준칙을 말한다. 즉, 주어진 실질중립금리, 물가갭, GDP갭 등을 고려한 적정 정책금리 수준을 의미하는데 준칙금리는 it = rt* + t + 0.5(t - t* ) + 0.5yt(it: 준칙금리, rt*: 실질중립금리, t : 물가상승률, * t : 물가목표, yt: GDP갭률)의 공식으로 산출된다. 이 준칙에 의하면 중앙은행의 단기목표금리는 물가갭(실제 인플레이션율 - 목표 인플레이션율)과 GDP갭을 고려하여 각각 0.5의 가중치를 두고 결정된다는 것이다. 그래서 중앙은행은 현재 인플레이션율이 목표인플레이션율보다 높은 경우 금리를 올리고 반대의 경우 금리를 내리며, 실제GDP가 잠재GDP보다 높으면 금리를 올리고 반대에는 금리를 내리게 된다. 그러나 대부분의 중앙은행은 테일러 준칙에 따라 통화정책을 수행하기 보다는 이를 하나의 참고지표로 간주하고 있다. 그 이유는 다음과 같다. 이 세상에 완전한 경제모형은 존재하지 않으므로 물가갭과 GDP갭을 정확히 알 수 없다는 것이다. 또한 경제는 시시각각으로 변하기 때문에 계수값이 항상 0.5로 고정되어 있지도 않다. 끝으로 이들 값을 확실히 알고 있다 하더라도 통화정책은 경제에 영향을 미치는 데 상당한 시차가 존재하며 금융안정과 같은 책무에도 기여해야 하기 때문에 테일러가 제시한 물가갭과 GDP갭 뿐만 아니라 더 많은 정보와 요소가 통화정책 수행시 고려되어야 하기 때문이다.', related_words = '{}'::text[] WHERE id = 607;  -- 테일러 준칙(Taylor’s Rule)
UPDATE public.words SET meaning = '미국 예일대학교의 제임스 토빈(James Tobin) 교수가 1978년에 주장한 것으로 국제 투기자본(핫머니)의 급격한 자금유출입으로 각국의 통화가치가 급등락하여 통화위기가 촉발되는 것을 막기', detailed_meaning = '미국 예일대학교의 제임스 토빈(James Tobin) 교수가 1978년에 주장한 것으로 국제 투기자본(핫머니)의 급격한 자금유출입으로 각국의 통화가치가 급등락하여 통화위기가 촉발되는 것을 막기 위한 국경 간 자본이동 규제방안의 하나이다. 토빈은 단기성 외환거래에 세금을 부과할 경우 연간 수천억 달러의 자금을 확보할 수 있다고 주장하였는데, 이 제도는 일반 무역거래, 장기 자본거래, 그리고 실물경제에는 지장을 주지 않으면서 투기성자본에만 제약을 가한다는 장점이 특징이다. 1990년대 후반부터 핫머니가 세계적으로 문제화됨에 따라 1995년 미국의 반대에도 불구하고 선진 7개국 정상회의(G7)의 의제로 상정되었으며, G7은 산하에 연구그룹을 만들어 토빈세의 효과를 검토하기도 하였다. 또한 일부 유럽 국가들을 중심으로 토빈세 도입 움직임이 있었으나 순수한 의미의 ‘외환거래세’를 안정적으로 장기 시행한 국가는 사실상 없다고 할 수 있다. 하지만 토빈세의 목적과 유사하게 단기투기성 자본의 이동을 억제하기 위한 제도는 유럽, 남미, 아시아 일부 국가 등에서 아직도 다양한 형태로 시행되고 있다.', related_words = '{}'::text[] WHERE id = 608;  -- 토빈세(Tobin Tax)
UPDATE public.words SET meaning = '통합발행제도(Fungible Issue 또는 Reopening Issue)란 일정기간(3개월, 6개월, 1년 등) 동안 계속해서 발행하는 채권의 표면금리와 만기 등 발행조건을 일치시켜 그 기간', detailed_meaning = '통합발행제도(Fungible Issue 또는 Reopening Issue)란 일정기간(3개월, 6개월, 1년 등) 동안 계속해서 발행하는 채권의 표면금리와 만기 등 발행조건을 일치시켜 그 기간 동안발행한 채권을 동일한 채권으로 만드는 제도이다. 예를 들어 1년 동안 매주 채권을 발행한다고 가정할 경우, 통합발행제도가 없다면 총 48개(4x12개월)의 종목이 발생하나 3개월을 통합발행기간으로 할 경우에는 4종목(각각 3개월 동안 12번[4x3개월] 발행되는 채권은 동일한 채권이므로)으로 줄어들게 된다. 이처럼 통합발행제도는 유통되는 채권의 종목 수를 획기적으로 줄여 유통시장에서 종목당 채권의 유동성을 높이는 효과가 있다. 특히 채권을 장기로 발행할수록, 정례적이고 지속적으로 발행할수록 동 제도를 통해 수요를 증진하고 발행 비용을 절감할 수 있다. 현재 국채, 통화안정증권 등이 통합발행제도를 도 입·운영하고 있다.', related_words = '{}'::text[] WHERE id = 610;  -- 통합발행제도
UPDATE public.words SET meaning = '중앙은행이 공급한 본원통화는 예금은행의 신용창출과정을 통해 이의 수 배에 달하는 통화를 시중에 유통하게 한다.', detailed_meaning = '중앙은행이 공급한 본원통화는 예금은행의 신용창출과정을 통해 이의 수 배에 달하는 통화를 시중에 유통하게 한다. 통화승수(Money Multiplier)는 본원통화 한 단위가 이의 몇 배에 달하는 통화를 창출하였는가를 나타내는 지표로서 통화 총량을 본원통화로 나누어 산출한다. 통화승수는 현금통화 비율과 지급준비율에 의하여 결정되는데 현금통화 비율은 단기적으로는 안정적이라 할 수 있으며 지급준비율은 중앙은행에 의하여 정책적으로 결정된다. M(통화) = RB(본원통화) × k(통화승수), k = 1/{c+(1-c)r} (단 c는 현금통화 비율, r은 지급준비율). 참고로 2025년 3월 말 현재 우리나라의 본원통화 잔액(말잔기준)은 290조원이고, M1, M2, Lf, L의 잔액은 각각 1,308조원, 4,228조원, 5,760조원, 7,250조원으로 통화승수는 각각 4.51배, 14.59배, 19.88배, 25.01배를 기록하고 있다. 한편 동 승수의 장기추세를 보면 우리나라의 경우 대략 2008년 글로벌 금융위기 이후 각 통화승수가 장기적으로 낮아지는 모습을 보이고 있다.', related_words = ARRAY['중앙은행','본원통화','지급준비제도']::text[] WHERE id = 612;  -- 통화승수
UPDATE public.words SET meaning = '통화신용정책보고서는 한국은행이 통화신용정책 결정 내용과 배경, 향후 통화정책방향등을 종합적으로 정리해 국회에 정기적으로 제출하는 법정 보고서로, 한국은행법 제96조에 따라 연 2회 작성하고 있다.', detailed_meaning = '통화신용정책보고서는 한국은행이 통화신용정책 결정 내용과 배경, 향후 통화정책방향등을 종합적으로 정리해 국회에 정기적으로 제출하는 법정 보고서로, 한국은행법 제96조에 따라 연 2회 작성하고 있다. 동 보고서는 통화정책의 투명성과 책임성, 예측 가능성을 높이기 위한 핵심 수단으로 활용된다. 동 보고서는 국내외 경제 상황, 물가 흐름, 금융·외 ㅌ환시장 동향 등을 분석하여 통화정책 결정의 배경을 설명한다. 또한 기준금리 결정의 근거와 그에 따른 정책 기조, 금융중개지원대출 등 유동성 공급 수단의 운용 현황, 향후 정책 방향에 대한 전망과 함께 서술 대상 기간의 주요 경제 현안에 대한 심층 분석도 포함하고 있다. 통화신용정책보고서는 단순한 정책 결과 보고를 넘어, 한국은행이 경제를 어떻게 진단하고 어떤 철학과 전략으로 대응하고 있는지를 보여주는 중요한 정책 커뮤니케이 션 수단이다. 각 경제주체들은 통화신용정책보고서를 통해 한국은행의 통화신용정책 운영 상황을 보다 잘 이해하고, 향후 정책방향에 대해 합리적인 기대를 형성해 나갈 수 있다. 보고서는 한국은행 홈페이지에서 누구나 열람할 수 있으며, 주요 내용은 기자설명회및 동영상 등을 통해서도 공유된다.', related_words = '{}'::text[] WHERE id = 613;  -- 통화신용정책보고서
UPDATE public.words SET meaning = '중앙은행은 역사적으로 경제구조의 변화, 금융시장의 발달 정도 등에 따라 다른 형태의 통화정책 운영체제를 도입해 왔다.', detailed_meaning = '중앙은행은 역사적으로 경제구조의 변화, 금융시장의 발달 정도 등에 따라 다른 형태의 통화정책 운영체제를 도입해 왔다. 통화정책 운영체제는 명목기준지표(nominal anchor)를 기준으로 구분하는 것이 일반적이다. 이는 통화정책체계의 구성요소 중에 서 최종목표나 정책수단 등은 어느 나라에 있어서나 본질적으로 비슷하며 차이가 있다 고 하더라도 대개 정도의 문제라 할 수 있지만, 통화정책 수행에 있어 어떤 명목기준지표가 적합한지는 각국의 경제구조와 금융시장 발달 정도 등에 따라 달라지므로 상당히 큰차별성을 갖기 때문이다. 여기서 명목기준지표란 중앙은행이 최종목표와 연관성이 높다 고 생각하여 중점 관리하는 명목변수를 의미한다. 통화정책 운영체제는 명목기준지표를 통화량, 환율, 물가상승률 중 어느 것으로 하는지에 따라 각각 통화량목표제(monetary targeting), 환율목표제(exchange rate targeting), 물가안정목표제(inflation targeting) 로 나뉘어진다. 일각에서는 기존 통화정책 운영체제의 대안으로 명목GDP목표제 (nominal GDP targeting) 등과 관련한 논의도 이루어지고 있다.', related_words = ARRAY['통화정책체계(monetary policy framework)','물가안정목표제']::text[] WHERE id = 618;  -- 통화정책 운영체제 (Monetary Policy Regime)
UPDATE public.words SET meaning = '통화정책이 실물경제에 파급되는 경로에는 금리경로, 자산가격경로, 환율경로, 기대경로, 신용경로, 위험선호경로 등이 있다.', detailed_meaning = '통화정책이 실물경제에 파급되는 경로에는 금리경로, 자산가격경로, 환율경로, 기대경로, 신용경로, 위험선호경로 등이 있다. 금리경로는 중앙은행이 정책금리를 인하하면 단기시장금리와 함께 장기시장금리, 은행 여수신금리도 하락하여 기업투자와 가계소비가 늘어나고 이는 생산 증대 및 물가 상승으로 이어진다. 자산가격경로의 경우 중앙은행이 정책금리를 인하하면 주식, 부동산 등 자산의 가격이 상승하고, 이에 따라 부(富)가 증가(wealth effect) 하면서 투자와 소비가 늘어나게 되고 이는 생산 증대 및 물가 상승으로 이어진다. 환율경로의 경우 중앙은행이 정책금리를 인하하면 국내금리가 하락하고 원화로 표시된 금융자산의 수익률이 떨어지게 되어 경제주체들이 상대적으로 수익률이 높은 달러화 표시금융자산을 매입하고자 하게 되며 이 과정에서 원화를 팔고 달러를 사게 된다. 이때 달러화에 대한 초과수요로 원화가치가 하락(환율 상승)하면 수출이 증가하고 수입이 감소하여경상수지가 개선되고 환율 변화가 수입품 가격에 반영되어 물가상승압력으로 작용한다. 기대경로의 경우 중앙은행이 현 시점에서의 정책금리 조정뿐만 아니라 경제주체들의 미래 통화정책에 대한 기대, 경기전망 및 인플레이션 기대를 변화시킴으로써 소비 및 투자결정과 물가에 영향을 미치는 것을 말한다. 신용경로의 경우 중앙은행이 정책금리를 인하하면 기업과 가계에 대한 금융기관의 대출여력이 커져 투자가 증가하고 소비가 늘어나며 이는 생산 증대 및 물가 상승으로 이어진다. 한편 위험선호경로의 경우 완화적 통화정책은 금융기관의 위험선호도를 증대시키게 되며 이로 인해 고위험·고수익 대출 등을 중심으로 신용공급이 확대되면서 소비, 투자 등이 늘어나게 된다. 동 경로는 저금리 기조가 장기간지속될 경우 금융기관의 과도한 위험추구와 신용공급 확대로 이어지면서 경제 내 금융취약성이 커질 수 있다는 점에서 통화정책과 금융안정의 연관성을 보여주고 있다.', related_words = '{}'::text[] WHERE id = 619;  -- 통화정책 파급경로
UPDATE public.words SET meaning = '한 나라의 경제가 건강하게 유지되려면 경제규모에 맞는 적정량의 통화가 필요하다.', detailed_meaning = '한 나라의 경제가 건강하게 유지되려면 경제규모에 맞는 적정량의 통화가 필요하다. 경제규모에 비해 돈이 너무 많으면 인플레이션이, 너무 적으면 디플레이션이 발생하여 물가의 지속적 상승이나 실업 등의 문제가 발생하기 때문에 중앙은행은 경제에서 유통되는 화폐의 양을 적정 수준으로 관리해야 하는데 그러기 위해서는 우선 시중에서 유통되는 통화의 양을 정확하게 측정할 필요가 있다. 시중에 유통되고 있는 통화량을 나타내는 척도가 곧 통화지표이다. 통화지표는 통화를 어떻게 정의하는가에 따라 여러 가지가 있는 데 우리나라에서는 M1과 M2를 통화지표로, Lf와 L을 유동성지표로 이용하고 있다. M1 은 화폐의 지급결제수단으로서의 기능을 중시한 지표로 시중에 유통되는 현금에 예금취급기관의 결제성예금을 더한 것이다. M2는 M1에 예금취급기관의 각종 저축성예금, 시장성 금융상품, 실적배당형 금융상품, 금융채 및 거주자예금을 더한 것이다. 통화지표보다 포괄범위가 더 넓은 지표가 유동성지표인데 Lf는 M2에 예금취급기관의 만기 2년 이 상의 정기예적금, 금융채, 금전신탁과 생명보험회사의 보험계약준비금 및 증권금융의 예수금 등을 포함한다. L은 Lf에 기업 및 정부 등이 발행한 기업어음, 회사채 및 국공채등 유가증권을 포함한다. 한국은행은 외환위기 이전까지는 M2를 명목기준지표(target) 로 하여 그 증가율을 정하고 이를 달성하고자 하는 통화량목표제를 시행하였다. 그러나 1990년대 후반부터 새로운 금융상품의 출현, 금융시장의 발전 등으로 통화량과 실물변수간의 관계가 약화됨에 따라 한국은행은 여건 변화에 부합하는 새로운 통화정책 운용체계인 물가안정목표제를 1998년 도입하여 지금까지 운영하고 있다. 물가안정목표제 도입이후 통화량은 달성해야 하는 명목기준지표가 아니고 물가 및 경기 전망 등을 평가하는 정보변수로서 활용되고 있다.', related_words = '{}'::text[] WHERE id = 622;  -- 통화지표
UPDATE public.words SET meaning = '각 산업부문이 재화나 서비스의 생산에 사용하기 위하여 다른 산업으로부터 구매한 원재료, 연료 등 중간재별 투입액을 총투입액으로 나눈 것으로서 각 부문 생산물 1단위 생산에 필요한 중간재들의 단위를', detailed_meaning = '각 산업부문이 재화나 서비스의 생산에 사용하기 위하여 다른 산업으로부터 구매한 원재료, 연료 등 중간재별 투입액을 총투입액으로 나눈 것으로서 각 부문 생산물 1단위 생산에 필요한 중간재들의 단위를 나타낸다. 따라서 어떤 산업부문의 중간재 투입계수들을 모두 합하면 중간투입률이 되며 이와 같은 투입계수는 각 산업부문의 생산활동에서 생산기술구조, 즉 투입과 산출의 함수관계를 나타낸다고 할 수 있다. 한편, 투입계수를 산출함에 있어서는 물량단위에 의한 방법이 이상적이라고 할 수 있으나 모든 생산물의 공통적인 단위가 없으므로 금액에 의한 투입계수를 산출하는 것이 일반적인 방법이다.', related_words = ARRAY['최종수요/중간수요']::text[] WHERE id = 623;  -- 투입계수
UPDATE public.words SET meaning = '1968년 4월 국제통화기금(IMF) 이사회의 결의에 따라 국제유동성 부족에 대처하기 위하여 1970년 도입된 일종의 국제준비통화이다.', detailed_meaning = '1968년 4월 국제통화기금(IMF) 이사회의 결의에 따라 국제유동성 부족에 대처하기 위하여 1970년 도입된 일종의 국제준비통화이다. 1960년대 들어 미 달러화의 금태환에 대한 신뢰가 저하되면서 국제통화체제의 불안정이 초래되자 새로운 준비자산의 필요성이 대두되었다. 이에 대응하여 IMF가 1967년 SDR(Special Drawing Rights) 창출요강을 채택하고 이를 반영한 IMF 협정문 개정안을 1969년 7월 발효시킴에 따라 도입되었다. SDR의 가치는 도입 당시 미 달러화의 금 평가와 동일한 1SDR=1.2635달러= 금 0.888671그램(1/35온스)으로 설정되었으나 이후 미 달러화의 약세 지속으로 SDR의 가 치를 미 달러화에 고정시키는 것이 불합리하게 되었다. 이러한 문제점을 시정하기 위해 1974년부터 SDR의 가치를 여러 나라의 통화에 연결시키는 바스켓방식을 도입하였으며 현재는 미 달러화, 유로화, 파운드화, 엔화, 위안화의 5개 통화가 바스켓을 구성하고 있다. SDR의 도입에 따라 IMF 회원국은 국제수지가 악화하였을 때 IMF로부터 무담보로 국제유동성을 인출할 수 있는 권리를 보유하게 되었다. SDR은 IMF 총회의 의결을 통해 창출또는 말소되며, 창출된 SDR은 SDR에 관한 의무사항을 수락한 IMF 회원국에 배분된다. SDR의 배분은 IMF 쿼타 비중에 따라 배분하는 일반배분과 쿼타 비중과 상관없이 배분하는 특별배분으로 구분된다. 우리나라에 대한 SDR 누적배분액은 2009년 실시된 일반 및 특별배분에 따라 이전의 0.7억SDR에서 24억SDR로 증가하였으며 2021년 역대 최대 규모의 SDR 일반배분으로 82억 SDR을 추가로 배분받으면서 총 106억 SDR이 되었다.', related_words = ARRAY['국제통화기금(IMF)','복수통화바스켓제도','IMF 쿼타']::text[] WHERE id = 625;  -- 특별인출권(SDR)
UPDATE public.words SET meaning = '자산유동화증권(ABS; Asset-Backed Securities) 발행에는 자산보유자, 특수목적기구 (SPV), 자산관리자 및 신용평가기관 등이 참가하게 된다.', detailed_meaning = '자산유동화증권(ABS; Asset-Backed Securities) 발행에는 자산보유자, 특수목적기구 (SPV), 자산관리자 및 신용평가기관 등이 참가하게 된다. 이 경우 자산보유자는 기초자산의 법률적인 소유권을 SPV(Special Purpose Vehicle)에 양도하는 절차를 거치게 되는데이는 자산보유자와 기초자산간의 법률적 관계를 분리하기 위한 것이다. 자산보유자는 기초자산을 모아서(pooling) 이를 SPV에 양도하며 SPV는 양도받은 기초자산을 담보로 발행한 ABS를 투자자에게 매각하고 매각대금을 자산보유자에게 자산양도의 대가로 지급한 다. 현행 「자산유동화에 관한 법률」에 따르면 자산보유자는 금융기관, 한국자산관리공사, 한국토지주택공사 및 금융위원회가 인정한 법인 등이 될 수 있으며 특수목적기구(SPV) 는 유동화전문회사(SPC; Special Purpose Company), 신탁회사 및 자산유동화를 전문으로 하는 외국법인이 될 수 있다. 동 법률에 따른 SPC는 주식회사보다 설립이 간편한 유한회사의 형태로 설립되며 ABS의 발행 및 상환과 이에 부속된 업무만을 수행할 수 있다. SPC는 ABS를 한 번만 발행할 수 있기 때문에 자산보유자는 자산유동화를 실시할 때마다 별도의 SPC를 설립하여야 한다. 한편 신탁회사는 수익증권 형태의 ABS를 발행하는 경우 SPV로 활용된다. 즉 자산보유자가 신탁회사에 기초자산을 양도하면 이 자산으로부터 발생하는 현금흐름을 이용하여 원리금을 지급하는 수익증권을 발행하게 된다. 자산관리자는 실체가 없는 서류상의 회사인 SPC를 대신하여 기초자산에 대한 채권의 추심 또는 채무자 관리 등을 담당한다. 우리나라에서는 자산보유자, 신용정보업자 등이 자산관리자가 될 수 있는데 일반적으로 기초자산의 내용을 잘 파악하고 있는 자산보유자가 자산관리자가 된다.', related_words = ARRAY['자산유동화']::text[] WHERE id = 626;  -- 특수목적기구(SPV)
UPDATE public.words SET meaning = '파생금융상품(Financial Derivatives)은 그 가치가 통화, 채권, 주식 등과 같은 기초금융자산(underlying asset)의 가치변동에 의해 결정되는 금융상품을 말한다.', detailed_meaning = '파생금융상품(Financial Derivatives)은 그 가치가 통화, 채권, 주식 등과 같은 기초금융자산(underlying asset)의 가치변동에 의해 결정되는 금융상품을 말한다. 계약형태에 따라 크게 선도계약(forward contracts), 선물(futures), 옵션(options), 스왑(swaps) 등으로 구분된다. 계약형태별 파생금융상품의 특징을 보면, 먼저 선도계약과 선물은 기초금융자산을 미래 특정시점에 사고 팔기로 약정하는 계약이라는 점에서 동일한 성격을 가지나, 일반적으로 선도계약은 장외시장에서 거래당사자간에 직접 거래되거나 딜러나 브로커를 통해 거래가 이루어지는 데 반해, 선물은 정형화된 거래소를 통해 거래된다는 점 등에서 차이가 있다. 옵션은 기초자산을 미래의 특정시점에 특정 행사가격으로 매입(call)하거나 매각(put)할 수 있는 권리를 사고 파는 계약으로서, 기초자산 가격의 변화에 대해 비대칭적 손익구조(asymmetric payoffs)를 가진다. 옵션계약은 거래시점에 프리미엄을 지급한 다는 점에서 선도계약이나 선물과 차이가 있다. 스왑은 일반적으로 두 개의 금융자산 또는 부채에서 파생되는 미래의 현금흐름을 교환하기로 하는 계약으로서, 서로 다른 통화표시 채무의 원리금 상환을 교환하기로 약정하는 통화스왑(currency swaps)과 변동금리채무와 고정금리채무간의 이자지급을 교환하기로 약정하는 금리스왑(interest rate swaps) 등이 있다.', related_words = ARRAY['옵션','스왑']::text[] WHERE id = 628;  -- 파생금융상품
UPDATE public.words SET meaning = '페더럴펀드(Federal Funds)는 미 연방준비은행에 지급준비금 예치의무가 있는 예금은 행이 지급준비금 과부족을 조절하기 위해 여타 예금은행, 정부보증기관(government-', detailed_meaning = '페더럴펀드(Federal Funds)는 미 연방준비은행에 지급준비금 예치의무가 있는 예금은 행이 지급준비금 과부족을 조절하기 위해 여타 예금은행, 정부보증기관(government- sponsored enterprises) 등으로부터 무담보로 차입한 자금을 말한다. 동 자금이 거래되는 시장을 페더럴펀드시장(federal funds market)이라고 한다. 다만 글로벌 금융위기 및코로나19 위기 등으로 미 연준이 대규모 자산매입을 실시함에 따라 초과지준이 대폭 늘어나게 되면서 지급준비금 의무적립의 실효성이 크게 감소하였다. 미 연준은 이를 고려하여 2020.3월중 지급준비율을 0%로 조정하면서 지급준비 의무가 사라지게 되었다. 이에 따라 페더럴펀드시장의 일평균 거래규모도 글로벌 금융위기 이전보다 크게 축소되었다. 페더럴펀드 거래 만기는 대부분 익일물이며, 기일물(term federal funds)의 경우 만기 제한은 없으나 통상 1년을 넘지 않는다. 페더럴펀드시장의 구조를 보면, 지준을 적립할 수있는 상업은행, 저축대부조합(Savings and Loan Association), 상호저축은행(Mutual Savings Bank), 신용협동조합(Credit Union), 해외은행의 미국 지점 등은 페더럴펀드시장에서 자금 차입과 공급이 모두 가능하다. 반면 지준을 적립할 수 없는 정부기관, 정부보증기관, 국제기구 및 증권딜러(securities dealer) 등은 페더럴펀드시장에서 자금을 공급할 수는 있으나 차입할 수는 없다. 글로벌 금융위기 이후 미 연준은 풍부한 지준(ample reserve system) 하에서 지급준비금에 이자를 지급하는 지준부리(interest on reserve balances)와 함께 국채 등 자산을 담보로 시장에서 자금을 차입함으로써 유동성을 흡수하는 익일물 RP매각(overnight reverse repurchase agreement) 등 공개시장운영(open market operation)을 통해 페더럴펀드금리를 목표범위 내로 유도하고 있다.', related_words = '{}'::text[] WHERE id = 629;  -- 페더럴펀드
UPDATE public.words SET meaning = '평잔과 말잔은 금융기관의 업무에서 자주 사용되는 용어로, 각각 평균잔액(average balance)과 기말잔액(end-of period balance)의 줄임말이다.', detailed_meaning = '평잔과 말잔은 금융기관의 업무에서 자주 사용되는 용어로, 각각 평균잔액(average balance)과 기말잔액(end-of period balance)의 줄임말이다. 평잔(평균잔액)은 일정 기간의 일일 잔액을 합산한 후 해당 기간의 일수로 나눈 값으로 평균치를 의미한다. 예를 들어 3월 1일부터 3월 31일까지의 1개월 평잔은 각 날짜의 잔액을 합산한 후 31로 나눈 값이다. 은행 등은 이자 계산이나 수익 평가시 평잔을 주로 사용한다. 반면 말잔(기말잔액) 은 일정 기간의 말일 시점에서 측정된 잔액이다. 예를 들어 6월말이나 12월말의 잔액을 가리킨다. 은행 등은 결산이나 특정 시점의 잔액을 표시할 때 사용한다. 금융기관의 작성편의상 말잔이 용이함에도 평잔을 편제하는 이유는 기간 말일이 되면 경제주체의 자금 운용 행태가 크게 달라질 가능성이 있기 때문이다. 예를 들어 기업들은 분기말에 재무비율개선을 위해 자금을 상환하였다가 다음 분기 초에 다시 대출을 받는 행태를 보인다. 이러한 행태로 인해 분기말에 일시적으로 잔액이 감소할 수 있기 때문에 평잔을 관측할 필요 가 있다.', related_words = '{}'::text[] WHERE id = 630;  -- 평잔/말잔
UPDATE public.words SET meaning = '프로젝트 파이낸싱(PF; Project Financing)이란 석유개발, 탄광채굴, 조선소, 발전소, 고 속도로 건설 등 대규모 사업을 추진하는 경우 그 프로젝트에 필요한 대규모의 소요자금과 각종', detailed_meaning = '프로젝트 파이낸싱(PF; Project Financing)이란 석유개발, 탄광채굴, 조선소, 발전소, 고 속도로 건설 등 대규모 사업을 추진하는 경우 그 프로젝트에 필요한 대규모의 소요자금과 각종 금융수요를 충족하기 위해서 동원되는 다수의 금융수단이나 투자금융기법을 통칭하는 말이다. 실제로 프로젝트 파이낸싱은 다양한 형태로 설계 운용될 수 있는데 주요한 특징적 요소를 살펴보면 대체로 다음과 같다. 먼저 통상적인 금융기관의 신용공여가 차입자의 신용도에 대한 평가나 보유자산을 담보로 하여 이루어지는데 비해 PF는 프로젝트 자체의 사업성 즉, 그 경제성이나 향후 가능성을 바탕으로 한다는 점에서 특징이 있다. 둘째로 프로젝트에 대규모의 장기자금이 소요되는 데다 사업의 수익성이 높지만 위험부담도 그만큼 크기 때문에 다수의 금융기관이 참여하는 협조융자 형태를 취하고 관련 금융기관이 출자를 통해 모기업과는 별도의 특수목적법인(SPC) 즉 프로젝트회사를 설립하여동 회사에 자금을 지원하는 형태를 취하여 모기업과 프로젝트회사 간에 리스크를 분산시키는게 보통이다. 아울러 주도적인 금융기관은 단순한 자금공급원의 기능을 넘어 개발계획의 입안 및 사업성 검토, 입찰준비, 신용보강 등에 광범위하게 참여하고 다양한 유형의 직간접 금융기법을 결합시키는 투자금융서비스도 제공하게 된다. 유럽 미국 등지에서는 1960년대부터 많이 사용되어 왔고 우리나라에서는 지난 2000년대 이후 사회간접자본 (SOC) 투자, 부동산 개발 등을 중심으로 많이 활용되는 모습을 보이고 있다.', related_words = '{}'::text[] WHERE id = 634;  -- 프로젝트 파이낸싱
UPDATE public.words SET meaning = '한 나라에서 생산활동으로 발생된 소득은 노동, 자본 등 생산요소를 제공한 경제주체에 게 분배된다.', detailed_meaning = '한 나라에서 생산활동으로 발생된 소득은 노동, 자본 등 생산요소를 제공한 경제주체에 게 분배된다. 노동소득분배율은 국민소득(노동소득과 자본소득의 합)에서 노동소득이 차지하는 비중으로, 노동소득과 국민소득의 범위를 어떻게 인식하느냐(자영업자의 노동소득 추정 문제, 국민소득 산출시 고정자본소모의 포함 여부 등)에 따라 다양한 종류의 산식으로 측정이 가능하다. OECD 회원국을 비롯한 여러 국가와 국제기구들은 다양한 방법으로 노동소득분배율을 산출하고 있는데, 우리나라의 경우 한국은행에서 피용자보수비율(Ratio of Compensation of Employees to NI)을 발표하고 있다. 피용자보수비율은 좁은 의미의 국민소득(피용자보수와 영업잉여의 합)에서 피용자보수가 차지하는 비중을 의미한다. 피용자보수비율은 한 나라의 경제 구조나 소득불균형 분석 등에 이용될 수있다. 피용자보수비율은 일반적으로 노동의 가격이 자본의 가격보다 높을수록, 그리고 한 나라의 산업이 노동집약적일수록 그 값이 커지게 된다.', related_words = ARRAY['피용자보수','영업잉여']::text[] WHERE id = 640;  -- 피용자보수비율
UPDATE public.words SET meaning = '핀테크(FinTech)는 ‘금융’(finance)과 ‘기술’(technology)의 합성어로 디지털 기술 혁신을 통해 금융서비스를 획기적으로 효율화하거나 새 금융서비스를 개발하는 것을 뜻한다.', detailed_meaning = '핀테크(FinTech)는 ‘금융’(finance)과 ‘기술’(technology)의 합성어로 디지털 기술 혁신을 통해 금융서비스를 획기적으로 효율화하거나 새 금융서비스를 개발하는 것을 뜻한다. 이는 혁신의 정도에 따라 전통적(traditional) 핀테크와 신흥(emergent) 핀테크로 구분할 수 있다. 전통적 핀테크는 기존 금융서비스의 가치사슬 안에서 그 서비스의 효율을 높이는 역할을 한다. 즉 기존 금융서비스를 자동화하려는 금융회사가 가치사슬의 핵심에 위치하고 IT기업은 이를 보조하는 역할을 수행한다. 씨티은행이 블록체인 및 분산원장기술을 활용해서 디지털화폐(Citicoin)로 글로벌 본·지점을 연결하여 자금을 이체하는 시스템을 예시로 들 수 있다. 반면 신흥 핀테크는 플랫폼을 제공하는 IT기업이 가치사슬의 핵심을 맡고 기존 금융서비스 전달체계를 변혁하여 파괴적(disruptive) 속성을 갖는다. 지점이 없는 인터넷전문은행이 공인인증서 없는 비대면 거래로 기존 관행을 파괴함으로써 단기간에 대규모 고객을 확보하거나, 대출금리와 송금수수료도 파격적으로 낮춤으로써 기존 은행의 금리 및 수수료를 인하시키는 것을 예시로 들 수 있다. 이외에도 핀테크 사례로 서 인터넷뱅킹·모바일지급서비스·크라우드펀딩·P2P대출·로보어드바이저·스마트계약· 바이오인증 금융거래 등을 들 수 있다.', related_words = ARRAY['‌블록체인','분산원장기술','전자화폐','가상통화']::text[] WHERE id = 641;  -- 핀테크
UPDATE public.words SET meaning = '뉴질랜드 출신의 영국인 경제학자 필립스(W. Phillips)는 1958년 명목 임금상승률과 실업률이 역의 상관관계를 나타낸다는 것을 처음으로 관찰하였는데, 이러한 임금상승률과 실업률 사이의', detailed_meaning = '뉴질랜드 출신의 영국인 경제학자 필립스(W. Phillips)는 1958년 명목 임금상승률과 실업률이 역의 상관관계를 나타낸다는 것을 처음으로 관찰하였는데, 이러한 임금상승률과 실업률 사이의 반비례 관계를 나타내는 곡선을 필립스 곡선이라 한다. 즉 필립스는 1861 년에서 1957년 사이의 영국의 통계자료를 이용하여 실업률이 낮은 해에는 명목 임금상승률이 높고, 반대로 실업률이 높은 해에는 명목 임금상승률이 낮다는 사실을 발견하였다. 일반적으로 명목 임금상승률과 물가상승률은 비슷한 움직임을 보이기 때문에 물가상승률과 실업률 간의 안정적인 반비례 관계를 나타내는 곡선을 필립스 곡선이라 부른다. 이러한 필립스 곡선은 단순히 경험적 관계로부터 도출되었지만, 완전고용을 이루면(실업률이 낮으면) 물가상승률이 높아지고(물가불안정), 완전고용에서 멀어지면(실업률이 높으면) 물가상승률이 낮아지는(물가안정) 완전고용과 물가안정 사이의 상충관계를 밝힘으로써경제정책 분석에 크게 기여하였다.', related_words = ARRAY['실업률갭','자연실업률']::text[] WHERE id = 642;  -- 필립스곡선
UPDATE public.words SET meaning = '한계비용은 재화나 서비스를 한 단위 더 생산하는데 들어가는 비용의 증가분을 의미한 다.', detailed_meaning = '한계비용은 재화나 서비스를 한 단위 더 생산하는데 들어가는 비용의 증가분을 의미한 다. 즉 비용증가분을 생산증가분으로 나눈 값이다. 예를 들면, 생수 100병을 생산하는 데 10,000원의 비용이 소요된다면 생수 1병의 평균생산비용은 100원이다. 추가로 생수한 병을 더 생산하여 101병, 102병을 생산할 때 비용이 각각 10,080원, 10,150원이라면 생수 101병째의 한계비용은 10,080원 ­10,000원 = 80원, 102병째의 한계비용은 70 원이 된다. 생산의 경제성을 분석하는 데에 있어 비용이 얼마나 소요되는가도(10,080원→10,150원) 중요하지만 생산을 늘림에 따라 증가하는 추가적 비용이 어떻게 변하는가를 (80원→70원) 살피는 것도 매우 중요하다. 왜냐하면 생산의 목적이 이윤을 극대화하는 데있다면 반드시 한계비용의 움직임을 살펴보아야 판단할 수 있기 때문이다. 이는 수학적으로 어떤 함수값(총비용)의 최소는 변수(생산규모)의 미분값이 0이 되는 곳에서 결정되는 ㅎ 데, 한계의 개념은 바로 미분과 일맥상통한다는 것을 상기하면 이해될 수 있다. 일반적으로 생산이 증가하면서 한계비용은 점차 줄어들다가 어느 생산규모에 이르면 다시 늘어나 기 시작한다.', related_words = ARRAY['수확체감의 법칙','한계효용']::text[] WHERE id = 643;  -- 한계비용
UPDATE public.words SET meaning = '한국은행이 금융기관간 자금결제를 위하여 1994년 12월부터 가동 운영하고 있는 거액지급시스템으로 금융기관의 콜거래, 외환 및 증권매매 등에 따른 원화자금 이체는 대부분한은금융망을 이용하여', detailed_meaning = '한국은행이 금융기관간 자금결제를 위하여 1994년 12월부터 가동 운영하고 있는 거액지급시스템으로 금융기관의 콜거래, 외환 및 증권매매 등에 따른 원화자금 이체는 대부분한은금융망을 이용하여 한국은행에 개설된 당좌예금을 이용해 계좌이체하는 방식으로 처리한다. 한은금융망은 금융기관간 원화자금 이체 이외에 한국은행 대출금 지원 및 상환, 국고금 수납 등 한국은행과 금융기관간 자금이체를 처리하고 어음교환시스템, 지로시스템 등 소액지급시스템의 은행간 채권·채무 결제에도 이용된다. 한은금융망은 실시간총액결제방식에 다자간 동시처리결제(차액결제) 요소를 추가한 혼합형결제방식으로 운영되고 있어 결제과정에서 신용리스크를 제거하는 동시에 일중 결제유동성도 절약할 수 있다. 이밖에 결제유동성을 효율적으로 관리하기 위하여 대기관리제도, 일중당좌대출제도 및일중RP제도, 반일물콜거래제도 등을 운영하고 있다. 2024년 12월말 현재 20개 국내은행을 포함하여 32개 외국은행 국내지점, 84개 비은행금융기관 등 총 136개 기관이 한은금융망에 참가하고 있다.', related_words = ARRAY['거액지급시스템','총액결제시스템','혼합형결제시스템']::text[] WHERE id = 648;  -- 한은금융망(BOK-Wire+)
UPDATE public.words SET meaning = '특정물품의 수입이 정부가 정한 일정수량에 이를 때까지는 저율의 관세가 부과되나 일정량을 초과하면 그 이후에는 고율의 관세가 부과되는 제도를 할당관세제도라고 하며 이때부과되는 고율 또는 저율의', detailed_meaning = '특정물품의 수입이 정부가 정한 일정수량에 이를 때까지는 저율의 관세가 부과되나 일정량을 초과하면 그 이후에는 고율의 관세가 부과되는 제도를 할당관세제도라고 하며 이때부과되는 고율 또는 저율의 관세를 할당관세라 한다. 할당관세제도는 특정물품의 국내총생산량이 총수요량에 미치지 못하는 상황에서 수입을 억제하려는 국내 생산자 측의 요구와 그 물품을 싼값으로 구매하려는 수요자 측의 상반된 요구를 동시에 충족시키기 위한 수단으로 사용된다. 이 제도는 자유무역의 확대를 위해서는 바람직하지 않으나 국내산업보호를 위해서는 필요하다는 점에서 WTO에서도 무차별 적용을 조건으로 인정해 주고 있다.', related_words = ARRAY['상계관세']::text[] WHERE id = 649;  -- 할당관세제도
UPDATE public.words SET meaning = '한 여성이 가임기간인 15세에서 49세 사이에 낳을 것으로 기대되는 평균 출생아 수를 측정하는 통계를 말하는데, 실제로는 5년 단위 간격으로 구분한 연령대별 출산율을 계산한 후 이를 합한 개념이기', detailed_meaning = '한 여성이 가임기간인 15세에서 49세 사이에 낳을 것으로 기대되는 평균 출생아 수를 측정하는 통계를 말하는데, 실제로는 5년 단위 간격으로 구분한 연령대별 출산율을 계산한 후 이를 합한 개념이기 때문에 합계출산율(Total Fertility Rate)이라고 부른다. 동 지표는 한 국가의 출산력 비교에 유용하게 쓰이고 있으며, 향후 인구는 물론 노동력의 변동을 가 늠하는 데 매우 유용한 지표로 활용되고 있다. 유럽경제위원회(UNECE)는 선진국에서 현재의 인구를 그대로 유지하는 데 필요한 합계출산율이 최소 2.1명이어야 한다고 추산한 바 있다. 우리나라의 합계출산율은 1982년 2.39명을 정점으로 1983년 2.03명으로 낮아진 이후 계속 떨어져 2023년에는 0.72명의 매우 낮은 수준을 기록하였다. 앞으로도 합계출산율 수준이 현 수준보다 크게 높아지지 않는 한 우리나라 인구가 2030년 이후에는 빠르게 감소할 것으로 예상되고 있다.', related_words = ARRAY['인구고령화']::text[] WHERE id = 650;  -- 합계출산율
UPDATE public.words SET meaning = '현금자동인출기(CD)공동망은 금융공동망 중계센터인 금융결제원과 금융기관들의 전산시스템을 상호 연결하여 특정 금융기관 고객이 다른 금융기관의 CD 또는 ATM을 이용하여 현금인출, 계좌이체,', detailed_meaning = '현금자동인출기(CD)공동망은 금융공동망 중계센터인 금융결제원과 금융기관들의 전산시스템을 상호 연결하여 특정 금융기관 고객이 다른 금융기관의 CD 또는 ATM을 이용하여 현금인출, 계좌이체, 잔액조회 등의 서비스를 받을 수 있도록 구축된 시스템으로 1988 년 7월 가동되었다. CD공동망의 가동으로 금융서비스의 장소적 제약이 제거되어 이용고 객은 현금카드만으로 모든 참가기관의 CD/ATM을 이용하여 손쉽게 현금인출 등 각종 서 비스를 이용할 수 있게 되었으며, 금융기관의 무인점포영업이 조기에 도입되는 계기가 마련되었다. CD공동망을 통하여 취급 가능한 업무는 현금인출, 신용카드 현금서비스, 계좌이체, 잔액조회, 지로대금 납부 등이며 이용대상 예금으로는 보통예금, 저축예금, 가계당좌예금, 기업자유예금, 신탁예금, 투자자예탁금 등이 있다.', related_words = ARRAY['소액지급시스템']::text[] WHERE id = 653;  -- 현금자동인출기(CD)공동망
UPDATE public.words SET meaning = '현시비교우위지수(RCA; Revealed Comparative Advantage Index)는 한 국가가 어떤 특정 품목에서 국제무역상 상대적으로 경쟁력이 있는지를 계량적으로 보여주는 지표이다.', detailed_meaning = '현시비교우위지수(RCA; Revealed Comparative Advantage Index)는 한 국가가 어떤 특정 품목에서 국제무역상 상대적으로 경쟁력이 있는지를 계량적으로 보여주는 지표이다. 이는 경제학자 Bela Balassa가 1965년에 제안한 지표로, 이론적 비교우위(comparative advantage)의 개념을 실제 무역 데이터를 통해 드러내기 위해 고안되었다. 말 그대로 ‘현시된(revealed)’ 비교우위란, 이론적 추정이 아닌 실제로 나타난 수출구조를 통해 비교우위가 있는지를 간접적으로 확인하는 것이다. 현시비교우위지수(RCA) 는 “RCAij = (Xij/Xit) / (Xwj/Xwt)”로 계산된다. 여기서 Xij는 국가 i의 품목 j 수출액, Xit 는 국가 i의 총 수출액, Xwj는 세계 전체의 품목 j 수출액, Xwt는 세계 전체의 총 수출액을 나타낸다. 즉, 특정 국가의 특정 품목이 자국 수출에서 차지하는 비중을 세계 총수출에서 의 해당 품목 수출비중과 비교하여 상대적 우위를 계산하는 방식이다. RCA가 1보다 크면해당 품목은 비교우위가 있다고 할 수 있다. 즉, 이 품목의 수출 비중이 세계 평균보다 높아서 상대적으로 경쟁력이 있다고 볼 수 있다. 예를 들어, 한국이 반도체 수출에서 RCA지수가 3.5라고 하면, 이는 한국의 반도체 수출 비중이 세계 평균보다 3.5배 더 높다는 뜻이다. 다시 말해, 한국은 반도체 산업에 대해 비교우위를 갖고 있음을 나타낸다.', related_words = ARRAY['수출경합도지수']::text[] WHERE id = 654;  -- 현시비교우위지수(RCA)
UPDATE public.words SET meaning = '혼합형결제시스템(Hybrid Settlement System)은 신용리스크가 발생하지 않는 실시간총액결제방식의 장점과 결제유동성을 절약할 수 있는 차액결제방식의 장점이 결합된 거액지급시스템을', detailed_meaning = '혼합형결제시스템(Hybrid Settlement System)은 신용리스크가 발생하지 않는 실시간총액결제방식의 장점과 결제유동성을 절약할 수 있는 차액결제방식의 장점이 결합된 거액지급시스템을 말한다. 혼합형결제방식은 차액결제를 영업시간이 끝난 이후 특정 시점으로 이연하지 않고 영업시간중에 수시로 수행함으로써 참가기관의 자금부담과 결제비용을 최소화하면서 일중에 결제완결성을 보장할 수 있는 특징이 있다. 혼합형결제시스템은 2000년대 들어 도입되기 시작하였는데 이는 금융 및 외환시장의 거래 규모가 확대되면서 금융기관들의 결제유동성 부담도 늘어나자 신용리스크 제거와 결제유동성 절약의 장점을 동시에 갖춘 혼합형결제방식이 새로운 결제방식으로 부각되었기 때문이다. 우리나라는 2005년 4월부터 본격적으로 한은금융망 재구축 사업에 착수하였으며 2009년 4월에 혼합형결제방식을 반영한 새로운 거액지급시스템을 가동하게 되었다. 2009년 4월 동 결제방식 도입 당시에는 양자간 및 다자간 동시처리 유동성절감방식을 채택하였다가 2020 년 10월 차세대 한은금융망 가동 이후에는 시스템 부하를 가중시키는 ‘양자간 동시처리방식’을 폐지하고 ‘다자간 동시처리방식’만을 운영하고 있다.', related_words = ARRAY['총액결제시스템','차액결제시스템']::text[] WHERE id = 659;  -- 혼합형결제시스템
UPDATE public.words SET meaning = '화폐발행은 중앙은행인 한국은행의 독점적인 권한으로 금융시장에서 국공채 매입, 은행에 대출, 외환 매입, 금융기관의 예금 인출 요청 등의 형태로 화폐를 시중에 공급하는 것을 말한다.', detailed_meaning = '화폐발행은 중앙은행인 한국은행의 독점적인 권한으로 금융시장에서 국공채 매입, 은행에 대출, 외환 매입, 금융기관의 예금 인출 요청 등의 형태로 화폐를 시중에 공급하는 것을 말한다. 이렇게 발행된 화폐는 민간이 보유하거나 금융기관이 예금인출에 대비하여 보유하게 된다. 따라서 화폐발행액은 민간보유현금(정부부문의 시재금 포함)과 금융회사의 시재금을 합친 것이다. 금융기관 등으로 부터 지급준비금 등의 형태로 다시 중앙은행에 환수되는 화폐가 있으면 화폐발행액은 줄어들게 된다.', related_words = ARRAY['화폐환수']::text[] WHERE id = 662;  -- 화폐발행/화폐발행액
UPDATE public.words SET meaning = '화폐의 액면체계는 한 국가의 화폐를 구성하는 액면금액의 틀을 의미하는데, 보통 액면체계는 ‘일상적인 거래 편의 도모’라는 대원칙 아래 국가의 경제·사회적 여건과 국민의 화폐사용 습관의 영향을', detailed_meaning = '화폐의 액면체계는 한 국가의 화폐를 구성하는 액면금액의 틀을 의미하는데, 보통 액면체계는 ‘일상적인 거래 편의 도모’라는 대원칙 아래 국가의 경제·사회적 여건과 국민의 화폐사용 습관의 영향을 받는다. 화폐의 액면체계는 대부분 기본수(1·5·10 등)에 10의 승수(10, 100, 1000...)를 곱하여 액면의 크기를 높여가는 방식으로 정해진다. 액면체계는 크게 [1, 5]체계와 [1, 2, 5]체계로 구분할 수 있는데 [1,5]체계는 (1, 5, 10, 50, 100, 500) 등의 액면배열을 말하여 [1, 2, 5]체계는 (1, 2, 5, 10, 20, 50, 100, 200, 500) 등 의 액면배열을 말한다. 특정액면에서 2 대신 2.5를 사용하는 [1, 2.5, 5] 체계도 있는데보통 [1, 2, 5]체계로 분류한다. [1, 5] 체계는 우리나라, 중국, 일본 등 주로 동아시아 국가에서 채택하고, [1, 2, 5] 체계는 유럽을 비롯하여 세계적으로 대종을 이루고 있다. 액면 종류가 적으면 사용자가 은행권 액면을 쉽게 식별하고 계산이 용이한 이점이 있는 반면에 현금거래에 필요한 은행권 수량이 상대적으로 많아 불편하고 화폐 제조비용도 많이 드는 단점도 있다.', related_words = '{}'::text[] WHERE id = 663;  -- 화폐의 액면체계
UPDATE public.words SET meaning = '환경계정이란 1993년 UN이 경제활동과 환경 간의 상호 관계를 체계적으로 분석하기 위하여 국민계정의 위성계정 형태로 새로 도입한 「환경경제통합계정」(SEEA; System of', detailed_meaning = '환경계정이란 1993년 UN이 경제활동과 환경 간의 상호 관계를 체계적으로 분석하기 위하여 국민계정의 위성계정 형태로 새로 도입한 「환경경제통합계정」(SEEA; System of Integrated Environmental and Economic Accounts)을 말한다. 환경계정은 기존 국민계정의 편제 대상이 시장에서 거래되는 경제적 자본(economic capital)에만 국한되어 환경오염이나 자원고갈 등으로 인한 경제·사회적 비용을 반영하지 못하는 한계를 보완해 주기 위한 것으로서 토지, 광물 및 에너지 자원, 수자원, 동물자원, 수목 등과 같은 자연자본 (natural capital)도 경제적 자본(economic capital)과 마찬가지로 재화와 서비스의 생산에 이용되는 자산으로 취급하여 동 자산의 기초 및 기말 스톡과 기간 중 변동을 국민계정체계(SNA) 구조 및 분류에 따라 기록하도록 하고 있다. 즉 광물채굴 또는 산림벌채 등 에 따른 자연자산의 감모나 환경오염에 따른 환경자산의 질적 악화 등 사회적 환경손실분을 화폐로 평가하여 이를 기존의 국민소득지표인 국내순생산(NDP)에서 차감하여 「환경요인 조정 국내순생산」(EDP; Environmentally Adjusted Net Domestic Product)을 추계하게 된다. 언론이나 일부 학계에서 사용하고 있는 녹색GDP는 EDP에 가까운 개념이 라 할 수 있다.', related_words = ARRAY['녹색GDP','환경권']::text[] WHERE id = 664;  -- 환경계정
UPDATE public.words SET meaning = '환경권(Environmental Rights)이란 모든 국민이 건강하고 쾌적한 환경 속에서 인간답게 살 수 있는 권리를 말한다.', detailed_meaning = '환경권(Environmental Rights)이란 모든 국민이 건강하고 쾌적한 환경 속에서 인간답게 살 수 있는 권리를 말한다. 헌법에 나와 있는 환경권의 정의에 따르면, 모든 국민은 건강하고 쾌적한 환경에서 생활할 권리를 가지며, 국가와 국민은 환경보전을 위하여 노력하여야 한다고 규정되어 있다(헌법 제35조 1항). 이는 환경권이 공해로 오염된 환경으로부터 보호받기 위한 생존권적 기본권으로 모든 국민은 자신의 건강을 지키기 위해 환경관련행정기관이나 제3자에게 환경개선을 요구할 수 있음을 의미한다. 즉 환경권은 깨끗한 환경에서 건강하고 쾌적한 생활을 누릴 수 있는 포괄적 권리로 볼 수 있다. 따라서 이는 오염되고 불결한 환경으로부터 고통 받지 말아야 한다는 소극적인 권리와 함께 국가에 대해깨끗한 환경을 보전하고 조성해 달라고 요구할 수 있는 적극적인 권리도 포함한다.', related_words = ARRAY['탄소배출권','환경계정']::text[] WHERE id = 665;  -- 환경권
UPDATE public.words SET meaning = '1988년에 제정된 미국의 종합무역법에서 규정된 개념으로 동 법은 현저한 대미 무역흑자 및 상당한 경상수지 흑자를 보인 국가를 환율조작국으로 지정할 수 있다.', detailed_meaning = '1988년에 제정된 미국의 종합무역법에서 규정된 개념으로 동 법은 현저한 대미 무역흑자 및 상당한 경상수지 흑자를 보인 국가를 환율조작국으로 지정할 수 있다. 한편 2015년에 제정된 교역촉진법에 의거 미 재무부는 ① 대미 무역흑자 150억 달러 초과, ② 국내총생산(GDP) 대비 경상흑자 비율 3% 초과, ③ 정책당국이 연간GDP 대비 2%를 초과하는 달러를 순매수하고 순매수가 12개월 중 8개월 이상 지속되는 등의 세 가지 요건이 모두해당되는 국가를 심층분석대상국으로 지정할 수 있다. 따라서 교역촉진법상의 심층분석대상국은 사실상 종합무역법상 환율조작국 지정의 전 단계로 기능하고 있다. 미국 재무부는 종합무역법, 교역촉진법에 의해 매년 4월 및 10월 반기별로 주요 교역국의 외환 정책보고서(환율보고서)를 작성하여 의회에 제출한다. 환율조작국으로 지정되면 미국은 해당국에 환율 저평가 및 지나친 무역흑자 시정을 요청하며 1년이 지나도 개선되지 않으면 해당국에 대한 미국 기업들의 투자 제한, 해당국 기업들의 미국 연방정부와의 조달계약 체결제한, 국제통화기금(IMF)에 추가적인 감시 요청 등의 구체적인 제재를 할 수 있다. 한편 위의 세 가지 요건 중 두 가지 요건에 해당된 국가는 관찰대상국(monitoring list)으로 분류된 다. 한국은 2016년 4월 이후 2025년 6월 현재까지 환율관찰대상국으로 분류되고 있다.', related_words = ARRAY['스무딩오퍼레이션']::text[] WHERE id = 670;  -- 환율조작국
UPDATE public.words SET meaning = '환위험은 크게 회계적 환위험(또는 환산환위험)과 거래적 환위험으로 나누는데, 이중에 서도 회계적 환위험이란 해외지사 및 자회사의 재무제표를 모기업의 재무제표와 연결시키기 위해 자산과 부채의 가치를', detailed_meaning = '환위험은 크게 회계적 환위험(또는 환산환위험)과 거래적 환위험으로 나누는데, 이중에 서도 회계적 환위험이란 해외지사 및 자회사의 재무제표를 모기업의 재무제표와 연결시키기 위해 자산과 부채의 가치를 동일한 통화로 환산하는 과정에서 발생하는 환위험을 말한다. 환차손/환차익은 회계적 환위험과 관련되는 것으로, 한 경제주체가 외화 자산 또는 부채를 보유하고 있을 때 환율변동에 따라 자국 통화로 평가한 자산(부채)의 가치가 변동하게 되는데, 환율 변동에 따라 이익이 발생하면 환차익이라고 하고 반대로 손실이 발생하면 환차손이라고 한다. 예를 들어 외화자산이 외화부채보다 많은 경우(외환매입초과 포지션, over-bought positions 또는 long positions) 환율이 상승(하락)하면 환차익(손) 이 발생하고 반대로 외화부채가 외화자산보다 많은 경우(외환매도초과포지션, over-sold positions 또는 short positions) 환율이 상승(하락)하면 환차손(익)이 발생한다. 환차손이 발생할 위험을 관리하는 방법으로는 리드앤드래그, 매칭, 자산부채관리 등 기업 내부적으로 환위험을 최소화하는 내부적 관리기법과 은행과의 외환파생상품을 이용한 대응거래 등을 통해 환위험을 커버하는 외부적 관리기법이 있다.', related_words = ARRAY['외국환포지션']::text[] WHERE id = 672;  -- 환차손/환차익
UPDATE public.words SET meaning = '회사채란 민간기업이 비교적 장기로 불특정 다수로부터 설비투자 자금 등 거액의 자금을 조달하기 위하여 정해진 이자와 원금의 지급을 약속하면서 발행하는 채권을 말한다.', detailed_meaning = '회사채란 민간기업이 비교적 장기로 불특정 다수로부터 설비투자 자금 등 거액의 자금을 조달하기 위하여 정해진 이자와 원금의 지급을 약속하면서 발행하는 채권을 말한다. 공모발행(public offering)의 경우 인수기관인 증권사, 산업은행 등이 총액을 인수하여 발행하며 정보의 투명성 제고를 통한 투자자 보호를 위하여 증권신고서를 금융위원회에 제출하여야 한다. 사모발행(private placement)의 경우 발행기업이 최종매수자와 발행조건을 직접 협의하여 발행한다. 만기는 보통 1, 2, 3, 5, 10년 등으로 발행하는데 신용위험때문에 대체로 3년 이하가 주종을 이루고 있다. 발행금리는 동일만기 국고채 금리에 일정한 가산금리(신용스프레드)를 붙여 발행한다. 경제가 호황이여서 기업의 신용위험이 줄어든 경우에는 가산금리도 줄어드는 반면 반대의 경우에는 가산금리가 확대된다. 한편 회사채에는 신용평가기관이 평가한 신용등급이 부여되는데 이는 투자자에게 원리금 회수가능성에 대한 정보를 제공한다. 이와 같은 신용평가제도는 회사채 발행금리(결과적으로 는 가산금리에 영향)에 결정적인 영향을 미친다. 회사채는 원리금 지급능력이 양호한 투자적격등급(AAA~BBB)과 지급능력이 의문시되는 투기등급(C~D)으로 구분되며 투자적격등급은 우량등급(AAA~AA)과 비우량등급(A~BBB)으로 구분된다. 발행기업은 신용등 급이 좋을수록 발행금리를 낮춰 자금조달 비용을 절감할 수 있기 때문에 좋은 신용등급을 받기 위해 재무구조 개선 등의 노력을 하게 된다.', related_words = ARRAY['신용스프레드']::text[] WHERE id = 673;  -- 회사채
UPDATE public.words SET meaning = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다.', detailed_meaning = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여경기종합지수를 작성한다. 경기종합지수는 선행종합지수, 동행종합지수, 후행종합지수 3 개가 작성되고 있으며, 기준년도 수치가 100이 되도록 하여 산출하고 있다. 후행종합지수는 재고, 소비지출 등 실제 경기순환에 후행하여 변동하는 개별지표를 가공·종합하여 만 든 지표로서 현재 경기의 사후확인에 이용한다. 현재 후행종합지수의 구성 지표로는 생산자제품재고지수, 도시가계소비지출, 소비재수입액(실질), 상용근로자수, 회사채유통수익률 등이 있다.', related_words = ARRAY['경기종합지수','동행종합지수','선행종합지수']::text[] WHERE id = 676;  -- 후행종합지수
UPDATE public.words SET meaning = '2010년대 물리적, 디지털 및 생물학적 세계를 융합하여 사회·경제·산업 등 전반적으로 충격을 주는 새로운 기술 영역이 등장한다.', detailed_meaning = '2010년대 물리적, 디지털 및 생물학적 세계를 융합하여 사회·경제·산업 등 전반적으로 충격을 주는 새로운 기술 영역이 등장한다. 4차 산업혁명(4IR; Fourth Industrial Revolution)은 인공지능(AI), 빅데이터, 사물인터넷(IoT), 블록체인 등의 새로운 정보통신기술이 산업과 사회 전반에 가져온 근본적이고 혁신적인 변화를 말한다. 18세기초 증기기관 발명으로 인한 산업혁명(1차) 이후 19세기 후반 전기를 기반으로 한 대량생산체계, 20세기 중반 컴퓨터, 인터넷으로 인한 지식정보 혁명에 이은 4번째의 커다 란 변화이다. 이전 3번의 혁명처럼 일상은 물론 노동시장, 기업경영, 정부정책 등에 심 대한 영향을 주고 있다. 이 용어는 2016년 세계경제포럼(WEF)에서 회장인 클라우스 슈밥(Klaus Schwab)이 처음 사용하였다. 그는 「4차 산업혁명」이라는 저서에서 인공지능(AI)·로봇·사물인터넷·3D프린팅·자율자동차·양자컴퓨팅·나노테크 등의 기술을 4 차 산업혁명의 특징으로 보았다. 4차 산업혁명은 초연결성(hyperconnectivity), 초지능 (superintelligence), 더 빠른 속도(velocity), 더 많은 데이터 처리능력(volume), 더 넓은 파급 범위(scope) 등의 특성을 지니는 ‘초연결지능 혁명’으로 볼 수 있다. 한편, 4차산업혁명은 인공지능의 작업 대체로 인한 일자리 감소, 인간과 로봇(인공지능)의 공존, 개인정보 및 사생활 보호, 유전자 조작에 따른 생명윤리 등 새로운 과제도 낳고 있다.', related_words = ARRAY['빅데이터']::text[] WHERE id = 677;  -- 4차 산업혁명
UPDATE public.words SET meaning = '국제결제은행(BIS)의 바젤은행감독위원회(이하 ‘BCBS’)가 “국제업무를 수행하는 은행의 자기자본비율은 8%를 초과해야 한다”고 제정한 국제적인 통일기준으로, 은행 보유 자산에 내재된', detailed_meaning = '국제결제은행(BIS)의 바젤은행감독위원회(이하 ‘BCBS’)가 “국제업무를 수행하는 은행의 자기자본비율은 8%를 초과해야 한다”고 제정한 국제적인 통일기준으로, 은행 보유 자산에 내재된 리스크(위험가중자산) 대비 복원력(자기자본)의 비율로 산출한다. BCBS는 1988년 「바젤자기자본협약」(Basel Capital Accord)에 따라 신용리스크에 중점을 둔 자기자본규제(바젤Ⅰ) 비율을 처음 발표(실행은 1992년)하였으며, 1996년 1월부터는 시장리스크를 반영토록 하였다. 이후 운영리스크 등 다양한 리스크를 반영하고 규제 회피 등 에 대응하기 위해 2004년 6월 「바젤Ⅱ: 자기자본 측정 및 자기자본에 대한 국제적인 통일기준 개정체계」를 발표하였다. 그러나 2008년 글로벌 금융위기를 거치면서 규제자본의 질이 하락하고 8% 자기자본비율이 위기시 대규모 손실을 흡수하기에는 불충분하다는 우려가 제기되었다. BCBS는 G20 정상회의, 금융안정위원회(FSB) 등의 결정을 반영하여 2010년 12월 「바젤Ⅲ: 은행부문의 복원력 강화를 위한 글로벌 규제체계」를 발표하였다. 바젤Ⅲ는 규제자본의 질을 제고하기 위해 즉각적으로 손실 흡수가 가능한 보통주자본 중심으로 자본규제를 재편하고 非자본증권의 규제자본 인정범위를 엄격히 제한하였다. 또한 가장 양질의 자본인 보통주자본과 기본자본(보통주자본+기타기본자본)을 각각 4.5% 및 6% 이상 유지하도록 의무화하였다. 규제자본의 양적 확충 측면에서는 최소자기자본비율(8%)에 더하여 2.5%의 보통주자본을 추가 적립하도록 하는 자본보전완충자본(CCoB) 을 도입하는 한편 거시건전성 요인을 고려하여 경기대응완충자본(CCyB)과 시스템적 중요 은행에 대한 추가자본(SIB)을 부과하여 은행별·국가별로 자본을 추가 적립하도록 하였다. 한편 BCBS가 2017년 12월 발표한 바젤Ⅲ 최종안은 2023년 1월부터 시행되고 있는데, 우리나라를 포함한 6개국은 최종안의 도입을 완료하였으며 미국, 유럽연합 등은 2025년중 시행을 목표로 도입작업을 진행 중이다. 총자본(일반은행에 대한 2025년 규제기준) 바젤Ⅲ (최소비율) 보완자본 (Tier 2) 보통주자본(CET 1) AT 1 4.5% 6% 8.0% 총자본(국내 금융체계상 중요한 일반은행에 대한 2025년 규제기준) 바젤Ⅲ 기본자본(Tier 1) (최소비율보완자본+완충자본) 보통주자본(CET 1) 기타(Tier 2) 기본자본최소비율 CCoB ', related_words = ARRAY['위험가중자산','보통주자본','기타기본자본','기본자본']::text[] WHERE id = 678;  -- BIS 자기자본비율
UPDATE public.words SET meaning = '은행의 경영실태평가방식으로는 CAMEL-IR, ROCA 및 CACREL 방식이 있는데, 일반은행 본점 및 현지법인에 대해서는 CAMEL-IR 방식, 외은지점 및 국내 일반은행 국외지점에 대해서는', detailed_meaning = '은행의 경영실태평가방식으로는 CAMEL-IR, ROCA 및 CACREL 방식이 있는데, 일반은행 본점 및 현지법인에 대해서는 CAMEL-IR 방식, 외은지점 및 국내 일반은행 국외지점에 대해서는 ROCA 방식, 특수은행에 대해서는 CACREL 방식에 의해 평가한다. 은 행 본점 및 현지법인에 대해서는 과거 CAMELS 방식을 운영하였으나, 리스크 부문 제도 개선을 통해서 2012년 4분기부터 CAMEL-R 방식으로 변경하였으며, 2024년 4월부터는 내부통제를 별도 평가 부문으로 분리하여 CAMEL-IR 방식으로 변경하여 평가 하고 있다. CAMEL-IR 방식은 경영평가부문을 자본적정성(Capital adequacy), 자산건전성(Asset quality), 경영관리의 적정성(Management), 수익성(Earnings), 유동성(Liquidity), 내부통제(Internal controls), 리스크관리(Risk management) 등 7개 부문으로 구분·평가하고, ROCA 방식은 리스크관리(R), 경영관리 및 내부통제(Operational controls), 법규준수(Compliance), 자산건전성(A) 등 4개 부문으로 구분 평가한다. CACREL 방식은 자본적정성(Capital Adequacy), 자산건전성(Asset Quality), 법규준수(Compliance), 위험관리(Risk Management), 수익성 (Earnings), 유동성 ABC (Liquidity) 등 6개 부문으로 구성된다.', related_words = ARRAY['경영실태평가/은행경영실태 평가등급제도']::text[] WHERE id = 679;  -- CAMEL-IR 방식/ROCA 방식/ CACREL 방식
UPDATE public.words SET meaning = 'CLS은행은 외환결제리스크 감축에 관한 국제결제은행(BIS)의 권고에 따라 1999년 주요 국제 상업은행들이 세계 주요 통화가 게재된 외환거래의 동시결제를 구현할 목적으로 설립한', detailed_meaning = 'CLS은행은 외환결제리스크 감축에 관한 국제결제은행(BIS)의 권고에 따라 1999년 주요 국제 상업은행들이 세계 주요 통화가 게재된 외환거래의 동시결제를 구현할 목적으로 설립한 국제외환결제전문은행이다. 동 은행을 통해 외환거래를 결제하면 각 통화별 중앙은 행에 개설된 CLS은행 계좌를 통해 양 거래통화의 동시결제(PVP)가 이루어지므로 원금리스크를 제거할 수 있으며 다자간상계에 따른 결제유동성 절감효과도 거둘 수 있다. CLS 은행은 스위스 취리히에 소재한 CLS그룹지주회사(CLS Group Holdings)의 자회사로서 1999년 11월 미국 뉴욕에 설립되었으며, 2024년말 현재 전세계 70개 이상의 결제회원은행과 약 35,000개 이상의 제3자고객을 대상으로 원화 등 총 18개국 주요국 통화간 외환매매거래 등에 대해 결제서비스를 제공하고 있다.', related_words = ARRAY['Herstatt 리스크','외환동시결제(PVP)']::text[] WHERE id = 681;  -- CLS은행
UPDATE public.words SET meaning = 'CMO(Collateralized Mortgage Obligation)는 미국에서 발행되는 주택담보대출증권의 일종으로, 패스스루(pass-through) 증권 및 모기지를 기초자산으로 하며, 해당', detailed_meaning = 'CMO(Collateralized Mortgage Obligation)는 미국에서 발행되는 주택담보대출증권의 일종으로, 패스스루(pass-through) 증권 및 모기지를 기초자산으로 하며, 해당 자산에 서 발생하는 현금흐름을 만기, 이자율, 조기상환 민감도가 서로 다른 여러 개의 트렌치 (tranche)로 구조화함으로써 투자자의 다양한 선호에 부합하도록 설계된 상품이다. 대표적인 CMO 상품으로는 sequential, PAC, stripped MBS 등을 들 수 있다. sequential CMO는 기초자산에서 발생하는 현금흐름을 사전에 정해진 순서에 따라 각 tranche에 순차적으로 지급하는 상품으로, 선순위 tranche에 가장 먼저 원금 상환이 이루어지며 이 후 차순위 tranche의 원금 수령이 이어지는 구조로 선순위의 원금 상환 전 단계에서는 차순위 tranche에 이자만 지급된다. 듀레이션 측면에서 선순위 tranche의 듀레이션이 후순위 tranche보다 작으며 이러한 점은 투자기간이 짧은 투자자에게 투자유인으로 작용한다. PAC(Planned Amortization Class)는 조기상환 속도에 대한 상한 및 하한을 사전에 지정하여 조기상환 속도 변화에 따른 현금흐름의 불확실성을 완화하는 상품이다. 조기상환 속도가 지정된 범위 내에 있을 경우 PAC tranche가 예정된 원리금을 수령하게 되며, Support tranche가 초과되는 현금흐름을 흡수함으로써 PAC으로 유입되는 현금흐름을 안정화시킨다. Stripped MBS는 pass-through에서 발생하는 원금과 이자를 별도의 tranche로 각각 분리한 상품이다.', related_words = ARRAY['부채담보부증권(CDO)','주택저당증권(MBS)']::text[] WHERE id = 682;  -- CMO
UPDATE public.words SET meaning = 'FIMA Repo Facility(Foreign and International Monetary Authorities Repo Facility)는 미 연준이 외국 중앙은행 등이 보유하고 있는 미', detailed_meaning = 'FIMA Repo Facility(Foreign and International Monetary Authorities Repo Facility)는 미 연준이 외국 중앙은행 등이 보유하고 있는 미 국채를 환매조건부로 매입하여 미 달러화 자금을 외국 중앙은행 등에게 공급하는 제도이다, 미 연준은 코로나19 팬데믹에 대응하여 2020년 3월 이 제도를 한시적으로 도입하였다가 2021년 7월 상설제도로 전환하였다. 이 제도를 통해 외국 중앙은행 등은 보유 중인 미국 국채를 매도하지 않고 필요시 미 달러화 자금을 즉시 조달할 수 있게 되었다. 한국은행은 2021년 12월부터 필요시 FIMA Repo Facility를 이용하기로 미 연준과 합의하였다.', related_words = ARRAY['연방준비제도(FRS)/연방준비은행(FRB)','환매조건부매매/RP/Repo']::text[] WHERE id = 686;  -- FIMA Repo Facility
UPDATE public.words SET meaning = 'FOMO현상(Fear Of Missing Out)은 다른 사람들이 누리는 중요한 경험이나 투자 기회등을 자신만 놓치고 있다는 불안감이나 두려움을 느끼는 현상을 말한다.', detailed_meaning = 'FOMO현상(Fear Of Missing Out)은 다른 사람들이 누리는 중요한 경험이나 투자 기회등을 자신만 놓치고 있다는 불안감이나 두려움을 느끼는 현상을 말한다. 이는 타인과 비교하며 뒤처지는 것에 대한 불안, 사회적 고립에 대한 두려움 등으로 이어질 수 있다. 특히 현재와 같이 소셜 미디어의 발달로 인해 타인의 삶을 쉽게 접하게 되면서 포모 현상을 경험하는 사람들이 늘고 있다. 금융시장에서 발생하는 포모 현상은 투자자들이 다른 사람 들이 커다란 이익을 얻는 것을 보고 자신도 기회를 놓칠까 두려워 충동적으로 투자하는 심리를 말한다. 특히 암호화폐 시장과 같이 변동성이 큰 시장에서 자주 발생하며 주식시장의 버블 형성 과정에서도 두드러지게 나타나는 현상인데 감정적인 판단이 합리적인 분석보다 앞서는 경향을 보인다.', related_words = '{}'::text[] WHERE id = 687;  -- FOMO현상
UPDATE public.words SET meaning = 'IMF 스탠드바이협약(SBA; Stand-By Arrangement)은 국제통화기금(IMF)이 회원국과 체결하는 금융지원계약의 일종으로 회원국이 단기적인 국제수지 불균형이나 외환위기로 급격한', detailed_meaning = 'IMF 스탠드바이협약(SBA; Stand-By Arrangement)은 국제통화기금(IMF)이 회원국과 체결하는 금융지원계약의 일종으로 회원국이 단기적인 국제수지 불균형이나 외환위기로 급격한 외환부족 사태에 직면하게 되었을 때 IMF로부터 신속하게 자금을 지원받아 경제안정에 활용할 수 있도록 하는 제도이다. IMF 회원국은 기본적으로 국제수지 개선을 위해노력하겠다는 약속만으로 쿼타(quota, IMF에 납입한 자본금)의 25%(reserve tranche) 까지 인출이 가능하지만, 이를 초과하는 융자를 받기 위해서는 IMF와 별도의 스탠드바이 협약을 맺고 이 협약에서 정한 신용공여조건 및 관련 프로그램을 이행하여야 한다. 2025 년 4월 현재 연간으로는 쿼타의 200%까지, 누적으로는 최대 600%까지 지원이 가능하다.융자 기간은 일반적으로 12~24개월이고 최대 36개월을 넘길 수 없으며 4년 차부터 8분기에 걸쳐 상환하여야 한다.', related_words = ARRAY['IMF 쿼타','국제통화기금(IMF)']::text[] WHERE id = 698;  -- IMF 스탠드바이협약
UPDATE public.words SET meaning = '국제통화기금(IMF)에 대한 회원국의 출자금으로서 IMF 회원국의 국제수지 불균형 조정등을 위한 신용공여 재원으로 사용될 뿐 아니라 투표권을 산출하고 IMF 신용 이용한도 와 특별인출권(SDR)', detailed_meaning = '국제통화기금(IMF)에 대한 회원국의 출자금으로서 IMF 회원국의 국제수지 불균형 조정등을 위한 신용공여 재원으로 사용될 뿐 아니라 투표권을 산출하고 IMF 신용 이용한도 와 특별인출권(SDR) 배분규모를 결정하는 기준이 된다. 회원국별 쿼타 산출을 위하여 쿼 타공식(quota formula)을 마련하고 있지만 창설 회원국의 실제 쿼타가 회원국 간 정치적 협상에 의해 결정됨에 따라 쿼타공식에 의해 산출된 계산 쿼타와 실제 쿼타는 출발부터 큰 괴리를 보였다. IMF 쿼타의 증액은 일반증액 또는 특별증액으로 이루어지는데 일반증액은 5년을 초과하지 않는 기간마다 쿼타 정책 전반을 점검하는 일반검토의 결과에 따른 증액이고, 특별증액은 개별 회원국의 요청에 의한 증액이다. 특별증액의 경우 창설 당시 지나치게 낮게 책정되었던 일부 국가들의 쿼타를 현실화하기 위해 초기에는 빈번히 이 루어졌으나 1970년대 이후에는 예외적으로만 실시되어 왔다. 이후 신흥시장국의 경제성장으로 계산 쿼타와 실제 쿼타 간의 괴리가 확대됨에 따라 2006년 9월 이러한 괴리가 두드러진 한국, 중국, 터키, 멕시코에 대한 특별증액이 이루어진 바 있다. 2023년 IMF 16차일반쿼타 검토(GQR) 결과, 쿼타 총액은 2025년 말까지 약 7,060억 SDR로 확대될 예정이며 이에 따라 한국의 쿼타도 약 128억 SDR 수준으로 늘어날 전망이다.', related_words = ARRAY['국제통화기금(IMF)','특별인출권(SDR)']::text[] WHERE id = 699;  -- IMF 쿼타
UPDATE public.words SET meaning = '이론적으로 환율이 상승할 경우 수출은 늘어나고 수입은 줄어들어 경상수지가 개선된다.', detailed_meaning = '이론적으로 환율이 상승할 경우 수출은 늘어나고 수입은 줄어들어 경상수지가 개선된다. 그러나 현실에서는 초기에 경상수지가 악화되다가 어느 정도의 시간이 지난 후에야 경상수지가 개선되는 효과가 나타나는데, 이를 J커브효과라고 한다. 이는 환율의 상승으로 경상수지가 실질적으로 개선되기까지는 어느 정도의 시간이 소요되기 때문이다. 환율 상승으로 국내 수출품 가격이 하락하더라도 이러한 가격 하락에 대응하여 수출물량이 증가하기까지는 시간이 걸린다. 이에 따라 단기적으로는 수출가격에 물량을 곱한 수출금액이 오히려 감소하면서 경상수지가 악화된 후, 수출물량이 증가하면서 수출금액이 늘어나 경상수지가 개선된다. 이 과정에서 경상수지의 시간에 따른 변화를 그래프로 나타냈을 때 영문자‘J’처럼 보인다고 하여‘J커브효과’라는 이름이 붙었다.', related_words = ARRAY['수출입물가지수']::text[] WHERE id = 700;  -- J커브효과
UPDATE public.words SET meaning = 'MOVE(Merrill Lynch Option Volatility Estimate)는 미국 채권시장의 단기 변동성에 대한 시장의 기대치를 나타내는 지수로, BoA메릴린치가 발표한다.', detailed_meaning = 'MOVE(Merrill Lynch Option Volatility Estimate)는 미국 채권시장의 단기 변동성에 대한 시장의 기대치를 나타내는 지수로, BoA메릴린치가 발표한다. MOVE는 미국 국채의 1개월 만기 옵션의 변동성을 기초로 하여 산출되며, 대상이 되는 미국 국채 금리는 2년물, 5년물, 10년물, 30년물이다. MOVE가 급등하면 미국 국채 금리의 변동성이 커져서 금리예측이 어려워지고, 미 연준의 통화정책이나 경기 전망에 대해 불확실성이 커졌다는 신호이며, 신용시장 경색, 안전자산 선호 증가로 이어질 수 있다. 일반적으로 MOVE가 100이 상이면 채권시장이 불안정하다는 신호로 해석된다. VIX가 주식시장의 공포지수로 불리는 것처럼 MOVE는 채권시장의 공포지수로 불린다.', related_words = ARRAY['VIX','CVIX','옵션']::text[] WHERE id = 703;  -- MOVE
UPDATE public.words SET meaning = 'OIS는 Overnight Index Swap의 약자로 금융기관 간에 단기 변동금리와 고정금리를 일정 기간(주로 1일) 동안 서로 교환하는 금리스왑 계약을 말한다.', detailed_meaning = 'OIS는 Overnight Index Swap의 약자로 금융기관 간에 단기 변동금리와 고정금리를 일정 기간(주로 1일) 동안 서로 교환하는 금리스왑 계약을 말한다. 변동금리는 미 연준의 연방기금금리(Fed Funds Rate)나 한국의 콜금리와 같이 주로 익일물에 연동된다. OIS는 주로 금융기관이 단기금리 변동에 따른 위험을 헤지하기 위해 활용하는 수단이다. OIS의 계약 당사자들은 원금의 교환 없이 변동금리와 고정금리의 차액만을 정산한다.', related_words = ARRAY['금리스왑']::text[] WHERE id = 708;  -- OIS
UPDATE public.words SET meaning = 'P2P대출(Peer-to-Peer Lending)은 온라인상에서 자금공급자(투자자)와 자금수요자(차입자) 간 전통적인 금융회사의 중개 없이 자금중개가 이뤄지는 금융활동의 하나이다.', detailed_meaning = 'P2P대출(Peer-to-Peer Lending)은 온라인상에서 자금공급자(투자자)와 자금수요자(차입자) 간 전통적인 금융회사의 중개 없이 자금중개가 이뤄지는 금융활동의 하나이다. P2P(peer-to-peer)는 원래 인터넷망을 통해 개인 간에 자신의 음악·동영상·사진 등의 파일을 공유하는 서비스인데 이 개념을 금융에 접목한 것이다. 초기에는 개인 사이의 대출 중개에 집중하였으나 최근에는 기업에 대한 대출 중개 및 다른 금융서비스 제공까지그 업무영역을 확장하고 있다. 이러한 대출 형태는 나라마다 조금씩 차이가 있는데 미국의 경우 P2P대출 중개업자는 온라인으로 대출을 신청한 차입자의 관련 어음(notes)을 산업대부회사(ILC; Industrial Loan Company)로부터 매입하여 투자자에게 제공한다. 증권거래위원회(SEC)가 이 어음을 ‘증권’(securities)으로 해석하여 규제하고, 투자자는 이 증권을 유통시장에서 매도하여 중간에 투자금액을 회수할 수도 있다. 이에 기관투자가까지도 투자자로 참여함에 따라 P2P대출은 시장형 대출(marketplace lending)로도 표현된다. 반면 영국의 경우 소비자신용업이 가능한 P2P대출 중개업자가 투자자들에게서 모금한 자금을 차입자에게 ‘대출금’으로 집행하므로 미국의 ILC같은 여신금융기관은 별도 로 없다. 그래서 금융행위감독청(FCA)이 중개업자들의 자본건전성을 규제한다. 우리나라의 경우 대체로 ‘P2P대출정보’중개업자는 자회사인 대부업체로부터 매입한 ‘원리금수취권리’를 투자자에게 매도하고, 대부업체에게서 대출받은 차입자가 원리금을 상환하면, 이 것이 다시 투자자에게 돌아간다. 그래서 대부업관련 법률을 적용받는다. 금융위원회는 투자자·차입자 등을 보호하기 위해 ‘P2P대출 가이드라인’(2017.2.27)을 도입하여 개인당 P2P대출정보 중개업자별 투자한도(1천만원) 설정, P2P업체 자산과 투자자 예치금의 분 ABC 리 예치, 과장광고 금지 등의 규제를 시행하였으며 최근에는 「온라인투자연계 금융업 및이용자 보호에 관한 법률」이 2025년 8월 27일부터 시행될 예정임에 따라, 기존의 가이드라인도 동 법령과 연계해 일부 개정 및 확대 적용될 예정이다.', related_words = ARRAY['자산유동화증권','Secondary-CBO']::text[] WHERE id = 709;  -- P2P대출
UPDATE public.words SET meaning = '유동화를 목적으로 설립된 특수목적회사(SPC; Special Purpose Company)가 부동산개발사업 PF(Project Financing) 대출을 기초자산으로 하여 발행한', detailed_meaning = '유동화를 목적으로 설립된 특수목적회사(SPC; Special Purpose Company)가 부동산개발사업 PF(Project Financing) 대출을 기초자산으로 하여 발행한 기업어음(Asset- Backed Commercial Paper)을 말한다. 부동산 개발사업 시행사가 PF-ABCP를 이용할경우 금융기관이 아닌 투자자로부터 자금을 조달하는 효과가 있어 투자자 확보가 용이하고 조달비용을 절감할 수 있는 장점이 있다. 투자자 입장에서도 시공사의 연대보증과 증권사 등에 의한 신용보강(매입보장, 매입확약 등)이 있기 때문에 직접 대출에 비해 리스크가 줄어드는 이점을 누릴 수 있다.', related_words = ARRAY['특수목적기구(SPV)']::text[] WHERE id = 710;  -- PF-ABCP
UPDATE public.words SET meaning = 'SOFR(Secured Overnight Financing Rate, 담보부 익일금리)은 미국채를 담보로 현금을 하루(overnight) 동안 빌릴 때 적용되는 실거래 기반의 기준금리로 뉴욕', detailed_meaning = 'SOFR(Secured Overnight Financing Rate, 담보부 익일금리)은 미국채를 담보로 현금을 하루(overnight) 동안 빌릴 때 적용되는 실거래 기반의 기준금리로 뉴욕 연준(FRB NY)이 발표하는 미달러화 단기금리의 대표적인 벤치마크이다. SOFR은 조작 가능성으로 신뢰성이 무너진 런던은행간금리(LIBOR)를 2023년 6월부터 공식적으로 대체하였다. SOFR은 미국채를 담보로 한 1일물 레포(환매조건부채권) 거래를 기초로 산출되므로 조작 위험이 낮고 시장의 실제 자금조달 비용을 반영한다는 장점이 있다. 또한 미국채라는 안전자산을 담보로 하기 때문에 신용위험이 거의 없는 ‘무위험 금리’로 간주되며 대출, 채권, 파생상품 등 다양한 시장에서 기준금리로 활용되고 있다.', related_words = '{}'::text[] WHERE id = 711;  -- SOFR
UPDATE public.words SET meaning = 'SWIFT(Society for Worldwide Interbank Financial Telecommunication)는 금융거래 관련 메시지를 안전하고 효율적으로 주고받기 위해 유럽 및 미주지역', detailed_meaning = 'SWIFT(Society for Worldwide Interbank Financial Telecommunication)는 금융거래 관련 메시지를 안전하고 효율적으로 주고받기 위해 유럽 및 미주지역 은행들이 1973 년 브뤼셀에 설립한 국제금융통신망이다. 금융기관간 자금이체, 고객송금, 신용장 개설및 통지, 외환거래, 추심, 유가증권, 신디케이트, 화환신용장 및 지급보증서, 여행자수표등에 관한 메시지 송수신에 주로 이용되며, CLS은행 등 국가간 결제시스템은 물론 일부국가의 중앙은행 거액지급시스템 통신망으로도 활용되고 있다. 2025년 7월 현재 전세계적으로 200여개국 11,000여개 금융기관이, 우리나라는 120여개 기관이 SWIFT를 이용중이다.', related_words = '{}'::text[] WHERE id = 712;  -- SWIFT
UPDATE public.words SET meaning = 'Treasury Bill(T/B)은 미국 재무성이 발행하는 만기 4주(1개월), 13주(3개월), 26주(6 개월), 52주(1년) 등 1년 이하의 단기국채로서 이자지급이 없는 할인채(zero', detailed_meaning = 'Treasury Bill(T/B)은 미국 재무성이 발행하는 만기 4주(1개월), 13주(3개월), 26주(6 개월), 52주(1년) 등 1년 이하의 단기국채로서 이자지급이 없는 할인채(zero coupon bond)의 형태로 발행된다. 단기금융시장의 여타 투자대상보다 수익률은 다소 낮지만, 대부분의 주에서 이자소득에 대한 주세(州稅)가 면제되며, 사실상 무위험(risk-free) 자산이 고 공급량도 많은 데다 상환기간도 다양하여 단기금융시장(money market)에서 투자자들에게 가장 안전하고 유동성이 높은 투자수단의 하나로 이용되고 있다. T/B의 유통은 이 자의 지급 없이 발행 당시에 할인되었던 가격으로 매매되고, 만기에 액면가격을 지급받는 방식으로 이루어진다. 금융시장의 조건에 의해 할인율이 결정되므로 T/B의 할인율은 시장금리를 나타내는 지표로 이용되며, 여타 채권의 벤치마크 기능, 위험헤지 수단, 국제채 ABC 권시장 동향지표 등으로 널리 활용되고 있다. T/B 이외의 미국 정부채로는 T-Notes(2∼ 10년), T-Bonds(20∼30년), 물가연동채(TIPS), 변동금리채(FRN) 등이 있다.', related_words = '{}'::text[] WHERE id = 713;  -- Treasury Bill(T/B)
UPDATE public.words SET meaning = 'V-KOSPI는 한국 증시의 변동성을 나타내는 지수로, 코스피200 옵션 가격을 기반으로 투자자들이 예상하는 미래 변동성을 측정한다.', detailed_meaning = 'V-KOSPI는 한국 증시의 변동성을 나타내는 지수로, 코스피200 옵션 가격을 기반으로 투자자들이 예상하는 미래 변동성을 측정한다. 이 수치는 미국 시카고옵션거래소(CBOE) 가 S&P 500 지수옵션을 토대로 발표하는 변동성지수(VIX)와 유사한 개념으로, 한국거래소(KRX)가 2009년 4월 13일부터 국내주식시장에 맞게 고안해 낸 아시아국가 최초의 변동성지수다. 주가가 급락할 때 변동성지수는 급등하는 역상관관계를 보이기 때문에 ‘공포지수(Fear Index)''라는 별명으로도 불리며 증시 시황 변동의 위험을 감지하는 중요한 투 ABC 자지표로 활용되고 있다. 주식시장에서의 변동성이 클 것이라고 예상하는 투자자가 많은 경우 지수가 올라간다. V-KOSPI가 상승하지 않는 것은 급락에 대한 불안감이 줄어들었다는 의미로, 투자심리가 견고하다는 뜻이 된다.', related_words = ARRAY['코스피200','변동성지수(VIX)','공포지수(Fear Index)']::text[] WHERE id = 714;  -- V-KOSPI

NOTIFY pgrst, 'reload schema';
